args.command:
cd /tmp/work-new/n4 && head -1 a.md b.md
/tmp/work-new/mkfull.sh /tmp/work-new/n5 && cd /tmp/work-new/n5 && cat > .zk/templates/showdate.md <<'EOF'
title={{title}}
now={{format-date now}}
date-short={{format-date now "2006-01-02"}}
date-time={{format-date now "2006-01-02 15:04:05"}}
{{content}}
EOF
echo "=== --date 2024-01-15 ==="; /workspace/executable new -t D --template showdate.md --date "2024-01-15" --dry-run 2>&1
echo "=== --date '2024-01-15 10:30' ==="; /workspace/executable new -t D --template showdate.md --date "2024-01-15 10:30" --dry-run 2>&1

cd /tmp/work-new/n5 && for f in short medium long full time iso year "%Y-%m-%d" "yyyy-MM-dd"; do cat > .zk/templates/fmt.md <<EOF
out={{format-date now "$f"}}
{{content}}
EOF
printf '=== fmt %q => ' "$f"; /workspace/executable new -t D --template fmt.md --date "2024-01-15" --dry-run 2>&1 | grep -E '^out=|error' | head -2; done

cd /tmp/work-new/n5 && cat > .zk/templates/fmt.md <<'EOF'
a={{format-date now "%A %B %d, %Y %H:%M:%S"}}
b={{format-date now "%s"}}
c={{format-date now "timestamp"}}
d={{format-date now "elapsed"}}
e={{format-date now "%Y"}}{{format-date now "%m"}}{{format-date now "%d"}}
{{content}}
EOF
/workspace/executable new -t D --template fmt.md --date "2024-01-15" --dry-run 2>/dev/null
echo "=== exact bad-date error bytes ==="; /workspace/executable new -t D --date "bogus" --dry-run > /tmp/work-new/o.txt 2>/tmp/work-new/e.txt; echo "exit=$?"; od -c /tmp/work-new/o.txt; od -c /tmp/work-new/e.txt

/tmp/work-new/mkfull.sh /tmp/work-new/n6 && cd /tmp/work-new/n6 && python3 - <<'EOF'
c=open('.zk/config.toml').read()
c=c.replace('#language = "en"','language = "fr"')
open('.zk/config.toml','w').write(c)
EOF
cat > .zk/templates/fmt.md <<'EOF'
short={{format-date now "short"}}
medium={{format-date now "medium"}}
long={{format-date now "long"}}
full={{format-date now "full"}}
{{content}}
EOF
/workspace/executable new -t D --template fmt.md --date "2024-01-15" --dry-run 2>/dev/null

/tmp/work-new/mkfull.sh /tmp/work-new/n9 && cd /tmp/work-new/n9 && cat > .zk/templates/extra.md <<'EOF'
k1={{extra.k1}}
k2={{extra.k2}}
missing={{extra.nope}}
{{content}}
EOF
echo "=== multiple --extra, = in value ==="; /workspace/executable new -t E --template extra.md --extra k1=v1 --extra k2=a=b=c --dry-run 2>/dev/null
echo "=== comma-separated ==="; /workspace/executable new -t E --template extra.md --extra k1=x,k2=y --dry-run 2>/dev/null
echo "=== bad extra (no =) ==="; /workspace/executable new -t E --template extra.md --extra novalue --dry-run; echo "exit=$?"
echo "=== empty value ==="; /workspace/executable new -t E --template extra.md --extra k1= --dry-run 2>/dev/null | head -1

cat /tmp/work-new/nbare/ewou.md | od -c
d=/tmp/work-new/nvars; rm -rf $d; /tmp/work-new/mkfull.sh $d; cd $d && cat > .zk/templates/vars.md <<'EOF'
id={{id}}
title={{title}}
filename={{filename}}
dir={{dir}}
path={{path}}
date={{date}}
now={{now}}
{{content}}
EOF
/workspace/executable new -t "Var Test" --id=myid --template vars.md --dry-run 2>/dev/null

cd /tmp/work-new/nvars && cat > .zk/templates/vars.md <<'EOF'
id={{id}}
title={{title}}
filename={{filename}}
dir={{dir}}
path={{path}}
now={{now}}
{{content}}
EOF
/workspace/executable new -t "Var Test" --id=myid --template vars.md --dry-run 2>/dev/null
echo "=== date helper usage ==="; cat > .zk/templates/dh.md <<'EOF'
a={{date now "short"}}
b={{date "2024-01-15" "%Y"}}
{{content}}
EOF
/workspace/executable new -t T --template dh.md --dry-run 2>&1 | head -5
